.\gradlew.bat assembleDebug --parallel --build-cache; if ($LASTEXITCODE -eq 0) { $apk=".\app\build\outputs\apk\debug\vaca-0.10.0-debug.apk"; adb devices | Select-Object -Skip 1 | % { $d=($_ -split "`t")[0]; if ($d) { echo "== $d =="; adb -s $d install -r -g $apk; if ($LASTEXITCODE -eq 0) { adb -s $d shell monkey -p com.msp1974.vacompanion -c android.intent.category.LAUNCHER 1 } } } }